def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    orth = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    around = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if (dr, dc) != (0, 0)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            markers = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if grid[y][x] != 1:
                    markers.append((y, x, grid[y][x]))
                for dy, dx in orth:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and not seen[yy][xx]:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            if not markers:
                continue
            # Multi-source shortest-path assignment lets different marker colors
            # label their respective parts when thin 1-cell bridges join regions.
            dist = {}
            owner = {}
            q = deque()
            for y, x, color in markers:
                if (y, x) not in dist:
                    dist[(y, x)] = 0
                    owner[(y, x)] = color
                    q.append((y, x))
            while q:
                y, x = q.popleft()
                for dy, dx in orth:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0:
                        nd = dist[(y, x)] + 1
                        if (yy, xx) not in dist:
                            dist[(yy, xx)] = nd
                            owner[(yy, xx)] = owner[(y, x)]
                            q.append((yy, xx))
            for y, x in cells:
                if grid[y][x] == 1 and all(
                    0 <= y + dy < h and 0 <= x + dx < w and grid[y + dy][x + dx] != 0
                    for dy, dx in around
                ):
                    out[y][x] = owner[(y, x)]
    return out
